(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7220],{1205:(e,n,a)=>{"use strict";a.r(n),a.d(n,{default:()=>l});var i=a(4568),t=a(5587),r=a.n(t),s=a(2829),d=a(5765);let o={en:{title:"About StyleNow",lead:"One place to find, book and run beauty appointments in Berlin — for the people in the chair and the people behind it.",s:[{heading:"What we do",body:"StyleNow is a booking marketplace for salons, barbers, nail and brow studios. Customers see live availability and fair, transparent prices — every surcharge and discount is named, never hidden. Salons get a full back office: calendar, team and roster, customers, messages, revenue, receipts."},{heading:"How booking works",body:"Seat before money: when you pick a time we hold the seat for a few minutes while you confirm, so two people can never buy the same chair. Prices include VAT. Deposits, cancellation windows and fees are the salon’s own policy and are shown before you pay, not after."},{heading:"Fair pricing, explained",body:'Some salons price quiet hours down and peak hours up. Wherever that happens, the price you see carries the reason — "Last-minute −20 %", "Saturday +10 %" — because a price you can’t explain is a price you can’t trust.'},{heading:"For salons",body:"Your own page with photos, opening hours derived from your real roster, a waiting list that turns cancellations into revenue, messaging with your customers, legally-shaped receipts, and staff who can see their own day and request their own time off."}],partner:"Run a salon? Partner with us →"},de:{title:"\xdcber StyleNow",lead:"Ein Ort, um Beauty-Termine in Berlin zu finden, zu buchen und zu verwalten — f\xfcr die Menschen im Stuhl und die dahinter.",s:[{heading:"Was wir machen",body:"StyleNow ist ein Buchungsmarktplatz f\xfcr Salons, Barbiere, Nagel- und Brauenstudios. Kundinnen und Kunden sehen echte Verf\xfcgbarkeit und faire, transparente Preise — jeder Auf- und Abschlag wird benannt, nie versteckt. Salons bekommen ein komplettes Backoffice: Kalender, Team und Dienstplan, Kundschaft, Nachrichten, Umsatz, Belege."},{heading:"So funktioniert Buchen",body:"Erst der Platz, dann das Geld: Wenn du eine Zeit w\xe4hlst, halten wir den Platz einige Minuten, w\xe4hrend du best\xe4tigst — zwei Personen k\xf6nnen nie denselben Stuhl kaufen. Preise inklusive USt. Anzahlungen, Stornofristen und Geb\xfchren sind die Regeln des jeweiligen Salons und stehen vor der Zahlung fest, nicht danach."},{heading:"Faire Preise, erkl\xe4rt",body:'Manche Salons machen ruhige Stunden g\xfcnstiger und Sto\xdfzeiten teurer. Wo das passiert, tr\xe4gt der Preis den Grund — „Last-minute −20 %", „Samstag +10 %" — denn ein Preis, den man nicht erkl\xe4ren kann, ist ein Preis, dem man nicht traut.'},{heading:"F\xfcr Salons",body:"Eine eigene Seite mit Fotos, \xd6ffnungszeiten direkt aus dem echten Dienstplan, eine Warteliste, die Stornierungen in Umsatz verwandelt, Nachrichten mit deiner Kundschaft, rechtssichere Belege — und ein Team, das den eigenen Tag sieht und Urlaub selbst beantragt."}],partner:"Du f\xfchrst einen Salon? Partner werden →"}};function l(){let{lang:e}=(0,s.s)(),n=o[e];return(0,i.jsx)(d.S,{title:n.title,lead:n.lead,sections:[...n.s.map(e=>({heading:e.heading,body:(0,i.jsx)("p",{children:e.body})})),{body:(0,i.jsx)(r(),{href:"/partner",className:"btn btn-primary",children:n.partner})}]})}},5412:(e,n,a)=>{Promise.resolve().then(a.bind(a,1205))},5765:(e,n,a)=>{"use strict";a.d(n,{S:()=>t});var i=a(4568);function t({title:e,lead:n,sections:a,aside:r}){return(0,i.jsxs)("div",{className:"info-page",children:[(0,i.jsxs)("header",{className:"info-head",children:[(0,i.jsx)("h1",{children:e}),n&&(0,i.jsx)("p",{className:"info-lead",children:n})]}),r,a.map((e,n)=>(0,i.jsxs)("section",{className:"info-section",children:[e.heading&&(0,i.jsx)("h2",{children:e.heading}),e.body]},n))]})}}},e=>{e.O(0,[5587,2829,587,1968,7358],()=>e(e.s=5412)),_N_E=e.O()}]);